#include <stdio.h>
#include <stdlib.h>

int longestSubarray(int* nums, int numsSize, int k) {
    int freq[100001] = {0};
    int left = 0, repeated = 0, ans = 0;

    for (int right = 0; right < numsSize; right++) {
        freq[nums[right]]++;

        if (freq[nums[right]] == 2)
            repeated++;

        while (repeated > k) {
            freq[nums[left]]--;
            if (freq[nums[left]] == 1)
                repeated--;
            left++;
        }

        if (right - left + 1 > ans)
            ans = right - left + 1;
    }

    return ans;
}

#include <limits.h>

int earliestFinishTime(int* landStart, int* landDur, int n,
                       int* waterStart, int* waterDur, int m) {
    int ans = INT_MAX;

    for (int i = 0; i < n; i++) {
        int landEnd = landStart[i] + landDur[i];

        for (int j = 0; j < m; j++) {
            int start = landEnd > waterStart[j] ? landEnd : waterStart[j];
            int end = start + waterDur[j];

            if (end < ans)
                ans = end;
        }
    }

    return ans;
}

#include <stdlib.h>

int cmp(const void* a, const void* b) {
    return (*(int*)b - *(int*)a);
}

int maxWeight(int* weights, int n) {
    qsort(weights, n, sizeof(int), cmp);

    int bag1 = 0, bag2 = 0;

    for (int i = 0; i < n / 2; i++)
        bag1 += weights[i];

    for (int i = n / 2; i < n; i++)
        bag2 += weights[i];

    return abs(bag1 - bag2);
}

#include <limits.h>

int maxBalancedShipments(int* weight, int n) {
    int ans = 0;
    int mn = weight[0];

    for (int i = 1; i < n; i++) {
        if (weight[i] > mn) {
            ans++;
            mn = INT_MAX;
        } else {
            if (weight[i] < mn)
                mn = weight[i];
        }
    }

    return ans;
}

#include <stdlib.h>

int trionic(int* nums, int n) {
    int* inc = (int*)malloc(sizeof(int) * n);
    int* dec = (int*)malloc(sizeof(int) * n);

    for (int i = 0; i < n; i++) {
        inc[i] = 1;
        dec[i] = 1;
    }

    for (int i = 1; i < n; i++) {
        if (nums[i] > nums[i - 1])
            inc[i] = inc[i - 1] + 1;
    }

    for (int i = n - 2; i >= 0; i--) {
        if (nums[i] > nums[i + 1])
            dec[i] = dec[i + 1] + 1;
    }

    int ans = 0;

    for (int i = 0; i < n; i++) {
        int len = inc[i] + dec[i] - 1;
        if (len > ans)
            ans = len;
    }

    free(inc);
    free(dec);

    return ans;
}

#include <stdbool.h>

bool isPalindrome(long long n) {
    long long rev = 0, temp = n;

    while (temp > 0) {
        rev = rev * 10 + temp % 10;
        temp /= 10;
    }

    return rev == n;
}

long long nextPalindrome(long long n) {
    n++;

    while (!isPalindrome(n))
        n++;

    return n;
}

#include <stdlib.h>

typedef struct {
    int severity;
    int exploitability;
} Threat;

int cmp(const void* a, const void* b) {
    Threat* t1 = (Threat*)a;
    Threat* t2 = (Threat*)b;

    if (t1->severity != t2->severity)
        return t2->severity - t1->severity;

    return t2->exploitability - t1->exploitability;
}

void sortThreats(Threat arr[], int n) {
    qsort(arr, n, sizeof(Threat), cmp);
}
